# Image indices refer to that listing's images (0 = the brief's store image); before/after, clinical-claim, award and
# review images are never used. 'fig' = store graphic with its own text (shown whole, never overlaid).

I = []
def item(sku, ch, slot, fmt, title, lead, facts, scenes, tags, hashtags, thumb):
    I.append(dict(sku=sku, ch=ch, slot=slot, format=fmt, title=title, lead=lead, facts=facts, scenes=scenes,
                  tags=tags, hashtags=hashtags, thumb=thumb))

